// Parse the official FAA Order JO 7340.2 company/designator table.
// The cached directory is refreshed daily and never blocks the radar flow.
const sourceUrl = "https://www.faa.gov/air_traffic/publications/atpubs/cnt_html/chap3_section_1.html";
const status = Number(msg.statusCode || 0);

function safeFailure(detail) {
    node.status({ fill: "yellow", shape: "ring", text: "FAA fallback list active" });
    node.warn(detail + " Embedded operator fallback remains active.");
    return { payload: { source: "FAA operator directory", message: detail, fallbackActive: true } };
}

if (status < 200 || status >= 300) {
    return safeFailure("FAA directory returned HTTP " + (status || "unknown") + ".");
}
if (typeof msg.payload !== "string" || msg.payload.length < 10000) {
    return safeFailure("FAA directory response was unexpectedly small or invalid.");
}

function decodeCell(value) {
    return String(value || "")
        .replace(/<[^>]*>/g, " ")
        .replace(/&nbsp;|&#160;/gi, " ")
        .replace(/&amp;/gi, "&")
        .replace(/&quot;/gi, '"')
        .replace(/&apos;|&#39;/gi, "'")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&#(\d+);/g, (match, number) => String.fromCodePoint(Number(number)))
        .replace(/\s+/g, " ")
        .trim();
}

const directory = {};
const rows = msg.payload.match(/<tr\b[\s\S]*?<\/tr>/gi) || [];
rows.forEach(row => {
    const matches = Array.from(row.matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/gi));
    if (matches.length !== 4) return;
    const cells = matches.map(match => decodeCell(match[1]));
    const code = cells[3].toUpperCase().replace(/[^A-Z0-9]/g, "");
    if (!/^[A-Z0-9]{3}$/.test(code) || !cells[0]) return;
    directory[code] = { company: cells[0], country: cells[1], telephony: cells[2] };
});

const count = Object.keys(directory).length;
if (count < 1000) {
    return safeFailure("FAA directory parser found only " + count + " valid designators.");
}

const updatedAt = new Date().toISOString();
flow.set("faaOperatorDirectory", directory);
flow.set("faaOperatorDirectoryMeta", { sourceUrl, updatedAt, count });
node.status({ fill: "green", shape: "dot", text: count + " FAA codes cached" });
return null;

const detail = msg.error && msg.error.message ? msg.error.message : "The FAA directory request could not be completed.";
node.status({ fill: "yellow", shape: "ring", text: "FAA fallback list active" });
return { payload: { source: "FAA operator directory", message: detail, fallbackActive: true } };

// OurAirports publishes this public-domain CSV nightly. A weekly refresh is enough
// for airport metadata and keeps the radar independent from this optional download.
const sourceUrl = "https://davidmegginson.github.io/ourairports-data/airports.csv";
const status = Number(msg.statusCode || 0);

function safeFailure(detail) {
    const prior = flow.get("ourAirportsDirectory");
    const cachedDataActive = Array.isArray(prior) && prior.length > 1000;
    node.status({ fill: "yellow", shape: "ring", text: cachedDataActive ? "cached airport directory active" : "airport directory unavailable" });
    node.warn(detail + (cachedDataActive ? " Cached airport directory remains active." : ""));
    return [null, { payload: { source: "OurAirports directory", message: detail, cachedDataActive } }];
}

if (status < 200 || status >= 300) {
    return safeFailure("OurAirports returned HTTP " + (status || "unknown") + ".");
}
if (typeof msg.payload !== "string" || msg.payload.length < 100000) {
    return safeFailure("OurAirports response was unexpectedly small or invalid.");
}

let header = null;
let indexes = null;
let row = [];
let field = "";
let quoted = false;
const airports = [];
const seen = {};

function consumeRow(values) {
    if (!header) {
        header = values.map(value => String(value || "").replace(/^\uFEFF/, "").trim());
        indexes = Object.fromEntries(header.map((name, index) => [name, index]));
        return;
    }
    if (!indexes || String(values[indexes.scheduled_service] || "").toLowerCase() !== "yes") return;
    const iata = String(values[indexes.iata_code] || "").trim().toUpperCase();
    const lat = Number(values[indexes.latitude_deg]);
    const lon = Number(values[indexes.longitude_deg]);
    if (!/^[A-Z0-9]{3}$/.test(iata) || !Number.isFinite(lat) || !Number.isFinite(lon) || seen[iata]) return;
    seen[iata] = true;
    airports.push({
        iata,
        ident: String(values[indexes.ident] || "").trim().toUpperCase(),
        name: String(values[indexes.name] || "").trim(),
        municipality: String(values[indexes.municipality] || "").trim(),
        type: String(values[indexes.type] || "").trim(),
        lat,
        lon
    });
}

const csv = msg.payload;
for (let i = 0; i < csv.length; i++) {
    const char = csv[i];
    if (quoted) {
        if (char === '"' && csv[i + 1] === '"') { field += '"'; i++; }
        else if (char === '"') quoted = false;
        else field += char;
    } else if (char === '"') quoted = true;
    else if (char === ",") { row.push(field); field = ""; }
    else if (char === "\n") { row.push(field); consumeRow(row); row = []; field = ""; }
    else if (char !== "\r") field += char;
}
if (field || row.length) { row.push(field); consumeRow(row); }

if (airports.length < 1000) {
    return safeFailure("OurAirports parser found only " + airports.length + " scheduled airports.");
}

const updatedAt = new Date().toISOString();
flow.set("ourAirportsDirectory", airports);
flow.set("ourAirportsMeta", { sourceUrl, updatedAt, count: airports.length });
node.status({ fill: "green", shape: "dot", text: airports.length + " scheduled airports cached" });
delete msg.url;
delete msg.headers;
msg.payload = { source: "OurAirports directory", updatedAt, count: airports.length };
return [msg, null];

const prior = flow.get("ourAirportsDirectory");
const cachedDataActive = Array.isArray(prior) && prior.length > 1000;
node.status({ fill: "yellow", shape: "ring", text: cachedDataActive ? "cached airport directory active" : "airport directory unavailable" });
return { payload: {
    source: "OurAirports directory",
    message: "The airport directory request could not be completed.",
    cachedDataActive
} };

// Optional AirLabs schedule enrichment. OpenSky live tracking remains independent.
// By default, select the nearest scheduled-service airport inside the radar radius.
const defaults = { airportIata: "", refreshMinutes: 120, maxRecords: 50, monthlyRequestCap: 900 };

function finiteNumber(value, fallback) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
}
function applyOverride(target, source) {
    if (!source || typeof source !== "object") return;
    if (source.airportIata != null) target.airportIata = String(source.airportIata).trim().toUpperCase();
    target.refreshMinutes = finiteNumber(source.refreshMinutes, target.refreshMinutes);
    target.maxRecords = finiteNumber(source.maxRecords, target.maxRecords);
    target.monthlyRequestCap = finiteNumber(source.monthlyRequestCap, target.monthlyRequestCap);
}
function distanceKm(lat1, lon1, lat2, lon2) {
    const toRad = value => value * Math.PI / 180;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
    return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const cfg = Object.assign({}, defaults);
applyOverride(cfg, global.get("openskyScheduleOverride"));
applyOverride(cfg, flow.get("openskyScheduleOverride"));
applyOverride(cfg, msg.scheduleConfig);
const envAirport = env.get("AIRLABS_AIRPORT_IATA");
if (envAirport) cfg.airportIata = String(envAirport).trim().toUpperCase();

if (cfg.airportIata && !/^[A-Z0-9]{3}$/.test(cfg.airportIata)) {
    node.error("AirLabs airport must be blank for automatic selection or a three-character IATA code.");
    return null;
}
if (cfg.refreshMinutes < 15 || cfg.refreshMinutes > 1440) {
    node.error("AirLabs refreshMinutes must be between 15 and 1440.");
    return null;
}
cfg.maxRecords = Math.max(1, Math.min(50, Math.round(cfg.maxRecords)));
cfg.monthlyRequestCap = Math.max(2, Math.min(100000, Math.round(cfg.monthlyRequestCap)));
cfg.estimatedMonthlyRequests = Math.ceil(43200 / cfg.refreshMinutes) * 2;

const radar = flow.get("openskyRadarConfig") || {};
const directory = flow.get("ourAirportsDirectory");
const centerLat = Number(radar.centerLat);
const centerLon = Number(radar.centerLon);
const radiusKm = Number(radar.radiusKm);
const canLocate = Number.isFinite(centerLat) && Number.isFinite(centerLon) && Number.isFinite(radiusKm);
let selected = null;

if (cfg.airportIata) {
    cfg.selectionMode = "manual";
    if (Array.isArray(directory)) selected = directory.find(airport => airport.iata === cfg.airportIata) || null;
} else if (canLocate && Array.isArray(directory) && directory.length) {
    directory.forEach(airport => {
        const distance = distanceKm(centerLat, centerLon, Number(airport.lat), Number(airport.lon));
        if (distance <= radiusKm && (!selected || distance < selected.distanceKm)) {
            selected = Object.assign({}, airport, { distanceKm: distance });
        }
    });
    if (selected) cfg.airportIata = selected.iata;
    cfg.selectionMode = "nearest-in-radius";
} else {
    cfg.selectionMode = "nearest-in-radius";
}

if (selected) {
    cfg.airportName = selected.name || "";
    cfg.airportMunicipality = selected.municipality || "";
    cfg.airportDistanceKm = Number.isFinite(selected.distanceKm)
        ? Math.round(selected.distanceKm * 10) / 10
        : (canLocate ? Math.round(distanceKm(centerLat, centerLon, Number(selected.lat), Number(selected.lon)) * 10) / 10 : null);
}
flow.set("openskyScheduleConfig", cfg);

// Never reuse schedule rows from a different location, even when AirLabs is disabled
// or the next request fails. This also handles caches created by older flow versions.
const previousAirport = String(flow.get("airlabsLastAirportIata") || "");
const existingCache = flow.get("airlabsScheduleCache") || {};
const cachedAirport = String(existingCache.airportIata || "");
if ((previousAirport && previousAirport !== cfg.airportIata) || (cachedAirport && cachedAirport !== cfg.airportIata)) {
    flow.set("airlabsScheduleCache", {});
    flow.set("airlabsLastRequestAt", 0);
}
if (cfg.airportIata) flow.set("airlabsLastAirportIata", cfg.airportIata);

const apiKey = env.get("AIRLABS_API_KEY");
if (!cfg.airportIata) {
    flow.set("airlabsScheduleMeta", {
        enabled: Boolean(apiKey), ready: false, selectionMode: cfg.selectionMode,
        message: Array.isArray(directory) ? "No scheduled-service airport was found inside the radar radius." : "Waiting for the public airport directory."
    });
    node.status({ fill: "grey", shape: "ring", text: Array.isArray(directory) ? "no scheduled airport in radar radius" : "waiting for airport directory" });
    return null;
}
if (!apiKey) {
    flow.set("airlabsScheduleMeta", {
        enabled: false, ready: true, airportIata: cfg.airportIata,
        airportName: cfg.airportName || "", airportDistanceKm: cfg.airportDistanceKm,
        selectionMode: cfg.selectionMode, message: "Set AIRLABS_API_KEY to enable optional schedules."
    });
    node.status({ fill: "grey", shape: "ring", text: "AirLabs disabled • " + cfg.airportIata + " selected" });
    return null;
}

const now = Date.now();
const lastRequestAt = Number(flow.get("airlabsLastRequestAt") || 0);
if (now - lastRequestAt < cfg.refreshMinutes * 60000) return null;

const month = new Date(now).toISOString().slice(0, 7);
let usage = flow.get("airlabsRequestUsage") || {};
if (usage.month !== month) usage = { month, count: 0 };
if (usage.count + 2 > cfg.monthlyRequestCap) {
    const meta = flow.get("airlabsScheduleMeta") || {};
    meta.quotaGuardActive = true;
    meta.monthlyRequestsUsed = usage.count;
    meta.monthlyRequestCap = cfg.monthlyRequestCap;
    flow.set("airlabsScheduleMeta", meta);
    node.status({ fill: "yellow", shape: "ring", text: "AirLabs monthly request guard reached" });
    return null;
}
usage.count += 2;
flow.set("airlabsRequestUsage", usage);
flow.set("airlabsLastRequestAt", now);

// Keep this list aligned with the documented v9 Schedules response fields.
const fields = [
    "flight_icao", "flight_iata", "flight_number", "airline_icao", "airline_iata",
    "cs_airline_iata", "cs_flight_iata", "cs_flight_number",
    "dep_iata", "dep_icao", "dep_terminal", "dep_gate",
    "dep_time", "dep_estimated", "dep_actual", "dep_delayed",
    "arr_iata", "arr_icao", "arr_terminal", "arr_gate", "arr_baggage",
    "arr_time", "arr_estimated", "arr_actual", "arr_delayed", "status"
].join(",");
const baseUrl = "https://airlabs.co/api/v9/schedules";
const batchId = now.toString(36);

function request(direction) {
    const airportParam = direction === "departures" ? "dep_iata" : "arr_iata";
    return {
        url: baseUrl + "?" + airportParam + "=" + encodeURIComponent(cfg.airportIata) +
            "&limit=" + cfg.maxRecords + "&_fields=" + encodeURIComponent(fields) +
            "&api_key=" + encodeURIComponent(apiKey),
        payload: "", _airlabsDirection: direction, _airlabsBatchId: batchId,
        _airlabsConfig: cfg
    };
}

flow.set("airlabsScheduleMeta", {
    enabled: true, ready: true, airportIata: cfg.airportIata,
    airportName: cfg.airportName || "", airportDistanceKm: cfg.airportDistanceKm,
    selectionMode: cfg.selectionMode, requestedAt: new Date(now).toISOString(),
    estimatedMonthlyRequests: cfg.estimatedMonthlyRequests,
    monthlyRequestsUsed: usage.count, monthlyRequestCap: cfg.monthlyRequestCap,
    quotaGuardActive: false
});
node.status({ fill: "blue", shape: "ring", text: "refreshing " + cfg.airportIata + " schedules" });
return [[request("departures"), request("arrivals")]];

// Keep only display fields. Never store or emit the request URL/API key.
const status = Number(msg.statusCode || 0);
const direction = msg._airlabsDirection === "arrivals" ? "arrivals" : "departures";
const cfg = msg._airlabsConfig || flow.get("openskyScheduleConfig") || {
    airportIata: "", refreshMinutes: 120, maxRecords: 50
};
delete msg.url;
delete msg.headers;

function safeFailure(detail, errorCode) {
    const prior = flow.get("airlabsScheduleCache") || {};
    const meta = flow.get("airlabsScheduleMeta") || {};
    meta.lastErrorAt = new Date().toISOString();
    meta.lastError = detail;
    meta.lastErrorCode = errorCode || "unknown";
    meta.usingStaleCache = Boolean(prior.staleUntil && prior.staleUntil > Date.now());
    flow.set("airlabsScheduleMeta", meta);
    node.status({
        fill: "yellow", shape: "ring",
        text: meta.usingStaleCache ? "AirLabs unavailable • cached schedules active" : "AirLabs schedule error"
    });
    return { payload: { source: "AirLabs schedules", message: detail, errorCode: meta.lastErrorCode, cachedDataActive: meta.usingStaleCache } };
}

if (status < 200 || status >= 300) {
    return safeFailure("AirLabs returned HTTP " + (status || "unknown") + ".", "http_" + (status || "unknown"));
}
const body = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
const documentedErrors = {
    unknown_api_key: "The AirLabs API key was not recognized.",
    expired_api_key: "The AirLabs API key has expired.",
    unknown_method: "The requested AirLabs endpoint is not supported.",
    wrong_params: "AirLabs rejected one or more request parameters.",
    not_found: "AirLabs did not find schedule data for this request.",
    minute_limit_exceeded: "The AirLabs per-minute request limit was reached.",
    hour_limit_exceeded: "The AirLabs hourly request limit was reached.",
    month_limit_exceeded: "The AirLabs monthly request limit was reached.",
    internal_error: "AirLabs reported an internal service error."
};
if (body.error && typeof body.error === "object") {
    const code = String(body.error.code || "unknown_api_error").toLowerCase().replace(/[^a-z0-9_]/g, "").slice(0, 80);
    return safeFailure(documentedErrors[code] || "AirLabs returned an API error.", code);
}
const rows = Array.isArray(body.response) ? body.response : (Array.isArray(body) ? body : null);
if (!rows) return safeFailure("AirLabs response did not contain a schedule list.", "invalid_response");

function text(value) {
    return value == null ? "" : String(value).trim();
}
function upper(value) {
    return text(value).toUpperCase();
}
function finite(value) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
}

const minimized = rows.slice(0, Number(cfg.maxRecords || 50)).map(row => ({
    flightIcao: upper(row.flight_icao),
    flightIata: upper(row.flight_iata),
    codeshareAirlineIata: upper(row.cs_airline_iata),
    codeshareFlightIata: upper(row.cs_flight_iata),
    codeshareFlightNumber: text(row.cs_flight_number),
    flightNumber: text(row.flight_number),
    airlineIcao: upper(row.airline_icao),
    airlineIata: upper(row.airline_iata),
    originIata: upper(row.dep_iata),
    originIcao: upper(row.dep_icao),
    destinationIata: upper(row.arr_iata),
    destinationIcao: upper(row.arr_icao),
    departureTerminal: text(row.dep_terminal),
    departureGate: text(row.dep_gate),
    departureScheduled: text(row.dep_time),
    departureEstimated: text(row.dep_estimated),
    departureActual: text(row.dep_actual),
    departureDelayMinutes: finite(row.dep_delayed),
    arrivalTerminal: text(row.arr_terminal),
    arrivalGate: text(row.arr_gate),
    arrivalBaggage: text(row.arr_baggage),
    arrivalScheduled: text(row.arr_time),
    arrivalEstimated: text(row.arr_estimated),
    arrivalActual: text(row.arr_actual),
    arrivalDelayMinutes: finite(row.arr_delayed),
    status: text(row.status).toLowerCase(),
    boardDirection: direction
})).filter(row => row.flightIcao || row.flightIata);

const previous = flow.get("airlabsScheduleCache") || {};
const boards = previous.airportIata === cfg.airportIata && previous.boards && typeof previous.boards === "object" ? previous.boards : {};
boards[direction] = minimized;
const byFlight = {};
Object.keys(boards).forEach(key => {
    (boards[key] || []).forEach(record => {
        [record.flightIcao, record.flightIata, record.codeshareFlightIata]
            .filter(Boolean)
            .forEach(code => { byFlight[code] = record; });
    });
});

const now = Date.now();
const requestUsage = flow.get("airlabsRequestUsage") || {};
const recordCount = Object.keys(boards).reduce((total, key) => total + (boards[key] || []).length, 0);
const matchKeyCount = Object.keys(byFlight).length;
const cache = {
    airportIata: cfg.airportIata,
    airportName: cfg.airportName || "",
    airportDistanceKm: cfg.airportDistanceKm,
    selectionMode: cfg.selectionMode,
    boards,
    byFlight,
    fetchedAt: now,
    expiresAt: now + Number(cfg.refreshMinutes || 120) * 60000 + 15 * 60000,
    staleUntil: now + 6 * 60 * 60000
};
flow.set("airlabsScheduleCache", cache);
flow.set("airlabsScheduleMeta", {
    enabled: true,
    airportIata: cfg.airportIata,
    airportName: cfg.airportName || "",
    airportDistanceKm: cfg.airportDistanceKm,
    selectionMode: cfg.selectionMode,
    updatedAt: new Date(now).toISOString(),
    records: recordCount,
    matchKeys: matchKeyCount,
    estimatedMonthlyRequests: cfg.estimatedMonthlyRequests,
    monthlyRequestsUsed: Number(requestUsage.count || 0),
    monthlyRequestCap: Number(cfg.monthlyRequestCap || 900),
    quotaGuardActive: false,
    usingStaleCache: false
});
node.status({ fill: "green", shape: "dot", text: recordCount + " schedules cached" });
return null;

// Do not forward the failed request message because msg.url contains the API key.
const prior = flow.get("airlabsScheduleCache") || {};
const cachedDataActive = Boolean(prior.staleUntil && prior.staleUntil > Date.now());
const meta = flow.get("airlabsScheduleMeta") || {};
meta.lastErrorAt = new Date().toISOString();
meta.lastError = "The AirLabs request could not be completed.";
meta.lastErrorCode = "network_error";
meta.usingStaleCache = cachedDataActive;
flow.set("airlabsScheduleMeta", meta);
node.status({
    fill: "yellow", shape: "ring",
    text: cachedDataActive ? "AirLabs unavailable • cached schedules active" : "AirLabs connection error"
});
return { payload: {
    source: "AirLabs schedules",
    message: "The schedule request could not be completed.",
    cachedDataActive
} };

// OpenSky request, location, and secret-safe OAuth configuration.
// Edit these defaults for your location. Polling can also be set with OPENSKY_POLL_SECONDS.
const defaultCenterLat = 25.7617;
const defaultCenterLon = -80.1918;
const defaultRadiusKm = 150;
const defaultPollSeconds = 300;

function finiteNumber(value, fallback) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
}

let cfg = {
    centerLat: defaultCenterLat,
    centerLon: defaultCenterLon,
    radiusKm: defaultRadiusKm,
    pollSeconds: defaultPollSeconds
};

// Optional runtime overrides. The effective config is stored separately in
// flow.openskyRadarConfig so changing the defaults above still takes effect.
function applyOverride(source) {
    if (!source || typeof source !== "object") return;
    cfg.centerLat = finiteNumber(source.centerLat, cfg.centerLat);
    cfg.centerLon = finiteNumber(source.centerLon, cfg.centerLon);
    cfg.radiusKm = finiteNumber(source.radiusKm, cfg.radiusKm);
    cfg.pollSeconds = finiteNumber(source.pollSeconds, cfg.pollSeconds);
}

applyOverride(global.get("openskyRadarOverride"));
applyOverride(flow.get("openskyRadarOverride"));
applyOverride(msg.config);
applyOverride(msg);
const envPollSeconds = env.get("OPENSKY_POLL_SECONDS");
if (envPollSeconds !== undefined && envPollSeconds !== "") {
    cfg.pollSeconds = finiteNumber(envPollSeconds, cfg.pollSeconds);
}

if (cfg.centerLat < -90 || cfg.centerLat > 90) {
    node.error("centerLat must be between -90 and 90", msg);
    return null;
}
if (cfg.centerLon < -180 || cfg.centerLon > 180) {
    node.error("centerLon must be between -180 and 180", msg);
    return null;
}
if (cfg.radiusKm < 1 || cfg.radiusKm > 500) {
    node.error("radiusKm must be between 1 and 500 km", msg);
    return null;
}
if (cfg.pollSeconds < 20 || cfg.pollSeconds > 3600) {
    node.error("pollSeconds must be between 20 and 3600 seconds", msg);
    return null;
}
cfg.pollSeconds = Math.round(cfg.pollSeconds);

const dLat = cfg.radiusKm / 111;
const safeCos = Math.max(Math.abs(Math.cos(cfg.centerLat * Math.PI / 180)), 0.05);
const dLon = cfg.radiusKm / (111 * safeCos);
const bounds = {
    lamin: Math.max(-90, cfg.centerLat - dLat),
    lamax: Math.min(90, cfg.centerLat + dLat),
    lomin: Math.max(-180, cfg.centerLon - dLon),
    lomax: Math.min(180, cfg.centerLon + dLon)
};

const areaSqDeg = (bounds.lamax - bounds.lamin) * (bounds.lomax - bounds.lomin);
const estimatedCreditCost = areaSqDeg <= 25 ? 1 : areaSqDeg <= 100 ? 2 : areaSqDeg <= 400 ? 3 : 4;

const clientId = env.get("OPENSKY_CLIENT_ID");
const clientSecret = env.get("OPENSKY_CLIENT_SECRET");
const authConfigured = Boolean(clientId && clientSecret);

cfg = Object.assign(cfg, bounds, {
    estimatedCreditCost,
    authConfigured
});
flow.set("openskyRadarConfig", cfg);

const dataUrl = "https://opensky-network.org/api/states/all" +
    "?lamin=" + bounds.lamin.toFixed(5) +
    "&lamax=" + bounds.lamax.toFixed(5) +
    "&lomin=" + bounds.lomin.toFixed(5) +
    "&lomax=" + bounds.lomax.toFixed(5) +
    "&extended=1";

msg.url = dataUrl;
msg.centerLat = cfg.centerLat;
msg.centerLon = cfg.centerLon;
msg.radiusKm = cfg.radiusKm;
msg.openskyConfig = cfg;

const mapKey = [cfg.centerLat, cfg.centerLon, cfg.radiusKm].join(":");
let mapMessage = null;
if (context.get("lastMapKey") !== mapKey) {
    context.set("lastMapKey", mapKey);
    mapMessage = { openskyConfig: cfg, _mapInit: true };
}

if (!authConfigured) {
    if ((clientId && !clientSecret) || (!clientId && clientSecret)) {
        node.warn("Both OPENSKY_CLIENT_ID and OPENSKY_CLIENT_SECRET are required; using anonymous access.");
    }
    msg._openskyAuthMode = "anonymous";
    node.status({ fill: "blue", shape: "ring", text: "anonymous • ~" + estimatedCreditCost + " credit/poll" });
    return [msg, null, mapMessage];
}

