        tooltip: "Radar Center • " + Number(cfg.radiusKm).toFixed(0) + " km range",
        popup: "<b>Radar Center</b><br>Latitude: " + Number(cfg.centerLat).toFixed(4) +
            "<br>Longitude: " + Number(cfg.centerLon).toFixed(4) +
            "<br>Search radius: " + Number(cfg.radiusKm).toFixed(0) + " km",
        contextmenu: ""
    }
};
return [commandMessage, rangeMessage, centerMessage];

// Convert transport failures into a visible map message and a safe Debug entry.
const detail = msg.error && msg.error.message ? msg.error.message : "The HTTP request could not be completed.";
const ui = {
    payload: {
        command: {
            toptitle: "OpenSky Radar • connection problem",
            showdialog: "<div style='font-family:system-ui;min-width:260px'><b>OpenSky connection problem</b><br>Check internet/DNS access from the Node-RED host. Existing aircraft remain visible during the refresh grace period.</div>"
        }
    }
};
const debug = { payload: { source: "OpenSky HTTP", message: detail } };
node.status({ fill: "red", shape: "ring", text: "OpenSky connection failed" });
return [ui, debug];

// This output is intentionally credential-free. It proves the flow is running even
// when the errors-only Debug node is empty.
const radar = flow.get("openskyRadarConfig") || {};
const radarStatus = flow.get("openskyRadarStatus") || {};
const operators = flow.get("faaOperatorDirectoryMeta") || {};
const airports = flow.get("ourAirportsMeta") || {};
const schedule = flow.get("openskyScheduleConfig") || {};
const scheduleMeta = flow.get("airlabsScheduleMeta") || {};
const usage = flow.get("airlabsRequestUsage") || {};

msg.topic = "OpenSky radar health";
msg.payload = {
    checkedAt: new Date().toISOString(),
    radar: {
        centerLat: radar.centerLat,
        centerLon: radar.centerLon,
        radiusKm: radar.radiusKm,
        aircraftCount: Number(radarStatus.aircraftCount || 0),
        airborne: Number(radarStatus.airborne || 0),
        grounded: Number(radarStatus.grounded || 0),
        updatedAt: radarStatus.updatedAt || null,
        authMode: radarStatus.authMode || (radar.authConfigured ? "Configured" : "Anonymous")
    },
    operators: { count: Number(operators.count || 0), updatedAt: operators.updatedAt || null },
    airports: {
        count: Number(airports.count || 0), updatedAt: airports.updatedAt || null,
        selectedIata: schedule.airportIata || null,
        selectedName: schedule.airportName || null,
        distanceKm: schedule.airportDistanceKm == null ? null : schedule.airportDistanceKm,
        selectionMode: schedule.selectionMode || null
    },
    schedules: {
        enabled: Boolean(scheduleMeta.enabled), ready: Boolean(scheduleMeta.ready),
        records: Number(scheduleMeta.records || 0), updatedAt: scheduleMeta.updatedAt || null,
        usingStaleCache: Boolean(scheduleMeta.usingStaleCache),
        monthlyRequestsUsed: Number(usage.count || scheduleMeta.monthlyRequestsUsed || 0),
        monthlyRequestCap: Number(schedule.monthlyRequestCap || scheduleMeta.monthlyRequestCap || 0),
        message: scheduleMeta.message || null,
        lastErrorCode: scheduleMeta.lastErrorCode || null
    }
};
return msg;

// AirLabs-only diagnostics. This message never includes the API key or request URL.
const cfg = flow.get("openskyScheduleConfig") || {};
const meta = flow.get("airlabsScheduleMeta") || {};
const cache = flow.get("airlabsScheduleCache") || {};
const usage = flow.get("airlabsRequestUsage") || {};
const fetchedAt = Number(cache.fetchedAt || 0);

msg.topic = "AirLabs schedule health";
msg.payload = {
    checkedAt: new Date().toISOString(),
    enabled: Boolean(meta.enabled),
    ready: Boolean(meta.ready),
    selectedAirport: cfg.airportIata || meta.airportIata || null,
    selectedAirportName: cfg.airportName || meta.airportName || null,
    distanceKm: cfg.airportDistanceKm == null ? null : cfg.airportDistanceKm,
    selectionMode: cfg.selectionMode || meta.selectionMode || null,
    records: Number(meta.records || 0),
    matchKeys: Number(meta.matchKeys || 0),
    updatedAt: meta.updatedAt || null,
    cacheAgeMinutes: fetchedAt ? Math.round((Date.now() - fetchedAt) / 6000) / 10 : null,
    usingStaleCache: Boolean(meta.usingStaleCache),
    refreshMinutes: Number(cfg.refreshMinutes || 120),
    estimatedMonthlyRequests: Number(cfg.estimatedMonthlyRequests || 0),
    monthlyRequestsUsed: Number(usage.count || meta.monthlyRequestsUsed || 0),
    monthlyRequestCap: Number(cfg.monthlyRequestCap || meta.monthlyRequestCap || 0),
    quotaGuardActive: Boolean(meta.quotaGuardActive),
    message: meta.message || null,
    lastErrorCode: meta.lastErrorCode || null,
    lastError: meta.lastError || null
};
return msg;
